// Chat uses callChat from @/lib/ai-chat (Claude or OpenAI)

// Helper function to get LLM-based query suggestions when no results found
async function getQuerySuggestions(queryType: string, userQuery: string, extractedParams: { division?: string | null, year?: number | null, wrestler?: string | null, name?: string | null }): Promise<string> {
  if (!hasChatKey()) {
    return ""
  }

  try {
    let formatExamples = ""
    if (queryType.includes("MOW")) {
      formatExamples = `For MOW queries, valid formats include:
- "MOW 4a 2025" or "4a MOW 2025"
- "Who was the 4A MOW in 2025?"
- "2025 MOWs" or "2025 States MOWs"
- "Who was MOWs at States in 2025?"`
    } else if (queryType.includes("wrestler") || queryType.includes("athlete")) {
      formatExamples = `For wrestler queries, try:
- Just the name: "Sebastian Rivera" or "Colton Palmer"
- Full name is usually best, but partial names may work
- Check spelling - names are case-sensitive
- Try asking: "What was [name]'s high school record?" or "Did [name] place at states?"`
    }

    const suggestionsPrompt = `You are a helpful assistant for a wrestling database. A user asked a question about ${queryType} but no results were found.

User's query: "${userQuery}"
Extracted parameters: ${JSON.stringify(extractedParams)}

Provide a brief, friendly suggestion (2-3 sentences max) that:
1. Acknowledges their query
2. Suggests correct query formats/examples
3. Mentions common misspellings or format issues if relevant

${formatExamples}

Keep the response concise and helpful.`

    const response = await callChat({
      model: "gpt-4o-mini",
      messages: [
        { role: "system", content: "You are a helpful assistant that provides query format suggestions for a wrestling database." },
        { role: "user", content: suggestionsPrompt }
      ],
      max_tokens: 150,
      temperature: 0.7,
    })

    return response.choices?.[0]?.message?.content?.trim() || ""
  } catch (err: any) {
    console.error("[AI] Error getting query suggestions:", err)
    return ""
  }
}

// Helper function to calculate cosine similarity
function cosineSimilarity(a: number[], b: number[]): number {
  if (a.length !== b.length) return 0
  let dotProduct = 0
  let normA = 0
  let normB = 0
  for (let i = 0; i < a.length; i++) {
    dotProduct += a[i] * b[i]
    normA += a[i] * a[i]
    normB += b[i] * b[i]
  }
  return dotProduct / (Math.sqrt(normA) * Math.sqrt(normB))
}


// Helper function to format school name with link to schools page
function formatSchoolLink(schoolName: string): string {
  const encoded = encodeURIComponent(schoolName)
  return `[**${schoolName}**](/schools?q=${encoded})`
}

// Helper function to load name aliases from database
async function loadNameAliasesFromDB(adminClient: any): Promise<Record<string, string>> {
  try {
    const { data: aliases, error } = await adminClient
      .from("name_aliases")
      .select("alias_name, canonical_name")
      .limit(1000) // Reasonable limit
    
    if (error) {
      // Table might not exist - that's okay, just use hardcoded map
      if (error.code === "42P01") {
        console.log("[AI] name_aliases table doesn't exist, using hardcoded aliases only")
        return {}
      }
      console.warn("[AI] Error loading name aliases from DB:", error)
      return {}
    }
    
    if (!aliases || aliases.length === 0) {
      return {}
    }
    
    // Convert to map: alias_name -> canonical_name
    const aliasMap: Record<string, string> = {}
    for (const alias of aliases) {
      const aliasLower = alias.alias_name?.toLowerCase().trim()
      const canonicalLower = alias.canonical_name?.toLowerCase().trim()
      if (aliasLower && canonicalLower) {
        aliasMap[aliasLower] = canonicalLower
      }
    }
    
    return aliasMap
  } catch (err) {
    console.warn("[AI] Exception loading name aliases:", err)
    return {}
  }
}

// Helper function to get reverse aliases (canonical -> aliases) from database
async function loadReverseNameAliasesFromDB(adminClient: any): Promise<Record<string, string[]>> {
  try {
    const { data: aliases, error } = await adminClient
      .from("name_aliases")
      .select("alias_name, canonical_name")
      .limit(1000)
    
    if (error) {
      if (error.code === "42P01") {
        return {}
      }
      console.warn("[AI] Error loading reverse name aliases from DB:", error)
      return {}
    }
    
    if (!aliases || aliases.length === 0) {
      return {}
    }
    
    // Group by canonical_name to get all aliases for each canonical name
    const reverseMap: Record<string, string[]> = {}
    for (const alias of aliases) {
      const canonicalLower = alias.canonical_name?.toLowerCase().trim()
      const aliasLower = alias.alias_name?.toLowerCase().trim()
      if (canonicalLower && aliasLower) {
        if (!reverseMap[canonicalLower]) {
          reverseMap[canonicalLower] = []
        }
        reverseMap[canonicalLower].push(aliasLower)
      }
    }
    
    return reverseMap
  } catch (err) {
    console.warn("[AI] Exception loading reverse name aliases:", err)
    return {}
  }
}

// Helper function to create school query pattern that prevents confusion
// between "Chapel Hill" and "East Chapel Hill"
function getSchoolQueryPattern(schoolName: string): string {
  const normalized = schoolName.toLowerCase().trim()
  
  // CRITICAL: "Chapel Hill" should use starts-with pattern to avoid matching "East Chapel Hill"
  if (normalized === "chapel hill") {
    return `${schoolName}%` // Starts with "Chapel Hill"
  }
  
  // CRITICAL: "East Chapel Hill" should use starts-with pattern to avoid matching "Chapel Hill"
  if (normalized === "east chapel hill") {
    return `${schoolName}%` // Starts with "East Chapel Hill"
  }
  
  // For other schools, use contains pattern for flexibility
  return `%${schoolName}%`
}

// Helper function to normalize school name using database function
// Falls back to basic normalization if RPC call fails
async function normalizeSchoolNameViaDB(adminClient: any, schoolName: string | null | undefined): Promise<string> {
  if (!schoolName || !schoolName.trim()) return ''
  
  try {
    // Try to use database normalization function via RPC
    const { data, error } = await adminClient.rpc('normalize_school_name', {
      input_name: schoolName.trim()
    })
    
    if (!error && data && typeof data === 'string' && data.trim()) {
      return data.trim()
    }
    
    // If RPC returned null or empty, log and fall through to client-side
    if (error) {
      console.warn('[AI] School normalization RPC error:', error.message || error)
    } else if (!data) {
      console.warn('[AI] School normalization RPC returned null/empty for:', schoolName)
    }
  } catch (err: any) {
    // RPC might not be available or function might not exist, fall through to client-side
    console.warn('[AI] School normalization RPC exception:', err?.message || err)
    // Don't throw - fall through to fallback
  }
  
  // Fallback: basic client-side normalization (matches database function logic)
  return schoolName
    .trim()
    .replace(/\s+High\s+School$/i, '')
    .replace(/\s+HS$/i, '')
    .replace(/\s+Academy$/i, '')
    .replace(/\s+School$/i, '')
    .replace(/\s+/g, ' ')
    .trim()
}

// Centralized helper function to check for common query type exclusions
// This ensures handlers don't overlap and makes the system order-independent
// Handles variations, misspellings, and natural language patterns
function getQueryTypeExclusions(lowerQuestion: string) {
  // Normalize common misspellings and variations
  const normalized = lowerQuestion
    .replace(/shultz/gi, "schultz")
    .replace(/schulz/gi, "schultz")
    .replace(/tricia\s+suanders/gi, "tricia saunders") // Common misspelling
    .replace(/super\s*32/gi, "super32")
    .replace(/all\s*[-]?\s*american/gi, "allamerican")
  
  return {
    // Award queries - handle variations and misspellings
    isAwardQuery: normalized.includes("dave schultz") || 
                  normalized.includes("schultz award") ||
                  normalized.includes("schultz winner") ||
                  lowerQuestion.includes("tricia saunders") || 
                  lowerQuestion.includes("saunders award") ||
                  lowerQuestion.includes("saunders winner") ||
                  lowerQuestion.includes("tricia suanders"), // Common misspelling
    
    // MOW queries - flexible matching
    isMOWQuery: lowerQuestion.includes("mow") || 
                lowerQuestion.includes("most outstanding") ||
                (lowerQuestion.includes("outstanding") && (lowerQuestion.includes("wrestler") || lowerQuestion.includes("mow"))),
    
    // State placement/championship queries - flexible patterns
    isStateQuery: lowerQuestion.includes("states") || 
                  lowerQuestion.includes("state championship") || 
                  lowerQuestion.includes("state champ") ||
                  lowerQuestion.includes("state placer") ||
                  lowerQuestion.includes("state place") ||
                  lowerQuestion.includes("nchsaa") ||
                  (lowerQuestion.includes("state") && (lowerQuestion.includes("won") || lowerQuestion.includes("champion") || lowerQuestion.includes("placer"))),
    
    // All-American queries - handle variations
    isAllAmericanQuery: normalized.includes("allamerican") || 
                        lowerQuestion.includes("all american") || 
                        lowerQuestion.includes("all-american") ||
                        (lowerQuestion.includes("all") && lowerQuestion.includes("american")),
    
    // NHSCA queries
    isNhscaQuery: lowerQuestion.includes("nhsca"),
    
    // Super32 queries - handle spacing variations
    isSuper32Query: normalized.includes("super32") || 
                    lowerQuestion.includes("super 32"),
    
    // Comparison queries - natural language patterns
    isComparisonQuery: lowerQuestion.match(/(?:who|which).*has.*more|compare.*vs|compare.*versus|.*vs.*|.*versus.*|better.*than|more.*than/i),
    
    // Count queries - natural language
    isCountQuery: lowerQuestion.includes("how many") || 
                  lowerQuestion.includes("count") ||
                  lowerQuestion.includes("number of"),
    
    // Most/best queries - flexible
    isMostQuery: (lowerQuestion.includes("most") || lowerQuestion.includes("best")) &&
                 !lowerQuestion.includes("most outstanding"), // Exclude MOW
    
    // School queries - flexible patterns
    isSchoolQuery: lowerQuestion.includes("high school") || 
                   (lowerQuestion.includes("school") && !lowerQuestion.includes("college")) ||
                   lowerQuestion.match(/[a-z]+\s+(high|school|academy|prep|christian|catholic|institute)/i),
    
    // College queries
    isCollegeQuery: lowerQuestion.includes("college") && 
                    !lowerQuestion.includes("high school"),
  }
}

// Centralized gender detection - recognizes girls, women, female (and male/men/boys)
// Uses word boundaries so "men" in "commitments" or "male" in "female" don't cause false matches
function isWomenGenderQuery(lowerQuestion: string): boolean {
  const hasWomen = lowerQuestion.includes("female") || lowerQuestion.includes("women") || lowerQuestion.includes("woman") ||
                   lowerQuestion.includes("girls") || lowerQuestion.includes("girl")
  const hasMen = /\bmale\b/.test(lowerQuestion) || /\bmen\b/.test(lowerQuestion) || /\bboys?\b/.test(lowerQuestion)
  return hasWomen && !hasMen
}
function isMenGenderQuery(lowerQuestion: string): boolean {
  return /\bmale\b/.test(lowerQuestion) || /\bmen\b/.test(lowerQuestion) || /\bboys?\b/.test(lowerQuestion)
}

// Helper function to strip name suffixes (Jr., II, III, etc.)
function stripNameSuffix(name: string): string {
  if (!name) return name
  // Remove common suffixes: Jr, Jr., II, III, IV, etc.
  return name.replace(/\s+(Jr\.?|II|III|IV|V|Sr\.?)$/i, "").trim()
}

// Helper function to get correct division for a college (overrides incorrect DB values)
function getCorrectDivisionForCollege(collegeName: string): string | null {
  if (!collegeName) return null
  const collegeLower = collegeName.toLowerCase().trim()
  
  // Map of colleges with incorrect divisions in the database
  const divisionCorrections: Record<string, string> = {
    "mckendree": "NCAA Division II",
    "unc pembroke": "NCAA Division II",
    "mount olive": "NCAA Division II",
    "emory & henry": "NCAA Division III",
    "roanoke": "NCAA Division III",
  }
  
  return divisionCorrections[collegeLower] || null
}

// Helper function to normalize division names to canonical forms
function normalizeDivision(division: string | null | undefined, collegeName?: string): string {
  if (!division) return "Unknown"
  
  // First, check if we need to correct the division based on college name
  if (collegeName) {
    const corrected = getCorrectDivisionForCollege(collegeName)
    if (corrected) {
      return corrected
    }
  }
  
  const divLower = division.toLowerCase().trim()
  
  // Normalize various spellings to canonical forms
  if (divLower.includes("division i") || divLower.includes("div i") || divLower.includes("di") || divLower === "d1" || divLower === "d i") {
    return "NCAA Division I"
  }
  if (divLower.includes("division ii") || divLower.includes("div ii") || divLower.includes("dii") || divLower === "d2" || divLower === "d ii") {
    return "NCAA Division II"
  }
  if (divLower.includes("division iii") || divLower.includes("div iii") || divLower.includes("diii") || divLower === "d3" || divLower === "d iii") {
    return "NCAA Division III"
  }
  if (divLower.includes("naia")) {
    return "NAIA"
  }
  if (divLower.includes("njcaa")) {
    return "NJCAA"
  }
  if (divLower.includes("independent")) {
    return "Independent"
  }
  
  // Return original if no match
  return division
}

// Helper function to normalize college and high school names for consistent grouping
function normalizeCollegeName(name: string | null | undefined): string {
  if (!name) return ""
  return name.trim().replace(/\s+/g, " ").replace(/\s*,\s*$/, "").replace(/\s+$/, "")
}

// Helper function to normalize common misspellings/typos before name matching
// This catches common typos like "almomd" -> "almond", "joesph" -> "joseph", "ezrah" -> "ezra"
function normalizeCommonMisspellings(name: string): string {
  const misspellingMap: Record<string, string> = {
    // Common letter transpositions and typos
    "almomd": "almond",
    "joesph": "joseph",
    "ezrah": "ezra",
    "johathan": "jonathan",
    "montoperto": "montaperto",
    // Add more as discovered from user queries
  }
  
  const lower = name.toLowerCase().trim()
  const parts = lower.split(/\s+/)
  
  // Normalize each part (first name, middle name, last name)
  const normalizedParts = parts.map(part => {
    // Direct misspelling match
    if (misspellingMap[part]) {
      return misspellingMap[part]
    }
    // Check for close matches (simple character difference check)
    for (const [misspelling, correct] of Object.entries(misspellingMap)) {
      // Simple check: if lengths are similar and most characters match
      if (Math.abs(part.length - misspelling.length) <= 2) {
        let differences = 0
        const minLen = Math.min(part.length, misspelling.length)
        for (let i = 0; i < minLen; i++) {
          if (part[i] !== misspelling[i]) differences++
        }
        differences += Math.abs(part.length - misspelling.length)
        // If 1-2 character difference, use correct spelling
        if (differences <= 2 && minLen > 3) {
          return correct
        }
      }
    }
    return part
  })
  
  return normalizedParts.join(" ")
}

// Helper function to normalize name variations (Tommy -> Thomas, etc.)
// Now accepts optional database alias map
function normalizeNameVariation(name: string, dbAliasMap?: Record<string, string>): string {
const nameMap: Record<string, string> = {
    "tommy": "thomas",
    "tom": "thomas",
    "mike": "michael",
    "mikey": "michael",
    "mick": "michael",
    "jim": "james",
    "jimmy": "james",
    "bob": "robert",
    "bobby": "robert",
    "rob": "robert",
    "dave": "david",
    "davey": "david",
    "dan": "daniel",
    "danny": "daniel",
    "chris": "christopher", // Note: "chris" can map to both "christopher" and "christian" - using "christopher" as primary
    "alex": "alexander", // Note: "alex" can map to both "alexander" and "alexandra" - using "alexander" as primary
    "nick": "nicholas", // Note: "nick" can map to both "nicholas" and "nicolas" - using "nicholas" as primary
    "jon": "jonathan", // Note: "jon" can map to both "jonathan" and "john" - using "jonathan" as primary
    "john": "jonathan",
    "will": "william",
    "bill": "william",
    "ed": "edward",
    "eddie": "edward",
    "ted": "edward",
    "joe": "joseph",
    "joey": "joseph",
    "sam": "samuel",
    "sammy": "samuel",
    "ben": "benjamin",
    "benny": "benjamin",
    "matt": "matthew",
    "nate": "nathaniel", // Note: "nate" can map to both "nathaniel" and "nathan" - using "nathaniel" as primary
    "josh": "joshua",
    "andy": "andrew",
    "drew": "andrew",
    "cam": "cameron",
    "pete": "peter",
    "brad": "bradley",
    "don": "donald",
    // Note: "jack" is NOT a nickname for "jackson" - they are separate names
    // "jack" stays as "jack", "jackson" stays as "jackson"
  }
  
  // Merge with database aliases if provided
  const mergedMap = dbAliasMap ? { ...nameMap, ...dbAliasMap } : nameMap
  
  const lower = name.toLowerCase().trim()
  return mergedMap[lower] || name
}

// Helper function to get all name variations (both nickname -> full name and full name -> nickname)
// This helps when searching - if someone searches "Matt", we should also try "Matthew"
// Now accepts optional database alias maps
async function getNameVariationsAsync(
  name: string, 
  adminClient?: any,
  dbAliasMap?: Record<string, string>,
  dbReverseMap?: Record<string, string[]>
): Promise<string[]> {
  const variations = [name.toLowerCase().trim()]
  
  // Load from DB if adminClient provided and maps not already loaded
  let aliasMap = dbAliasMap
  let reverseMap = dbReverseMap
  
  if (adminClient && !aliasMap) {
    aliasMap = await loadNameAliasesFromDB(adminClient)
  }
  if (adminClient && !reverseMap) {
    reverseMap = await loadReverseNameAliasesFromDB(adminClient)
  }
  
  const normalized = normalizeNameVariation(name.toLowerCase().trim(), aliasMap)
  
  // Add normalized version if different
  if (normalized !== name.toLowerCase().trim()) {
    variations.push(normalized)
  }
  
  // Also add reverse mappings (full name -> nickname)
  const hardcodedReverseMap: Record<string, string[]> = {
    "thomas": ["tom", "tommy"],
    "michael": ["mike", "mikey", "mick"],
    "james": ["jim", "jimmy"],
    "robert": ["bob", "bobby", "rob"],
    "david": ["dave", "davey"],
    "daniel": ["dan", "danny"],
    "christopher": ["chris"],
    "christian": ["chris"],
    "alexander": ["alex"],
    "alexandra": ["alex"],
    "nicholas": ["nick"],
    "nicolas": ["nick"],
    "jonathan": ["jon"],
    "william": ["will", "bill"],
    "edward": ["ed", "eddie", "ted"],
    "joseph": ["joe", "joey"],
    "samuel": ["sam", "sammy"],
    "benjamin": ["ben", "benny"],
    "matthew": ["matt"],
    "nathaniel": ["nate"],
    "nathan": ["nate"],
    "joshua": ["josh"],
    "andrew": ["andy", "drew"],
    "cameron": ["cam"],
    "peter": ["pete"],
    "bradley": ["brad"],
    "donald": ["don"]
  }
  
  // Merge with database reverse map if provided
  const mergedReverseMap = reverseMap 
    ? { ...hardcodedReverseMap, ...reverseMap }
    : hardcodedReverseMap
  
  const lower = name.toLowerCase().trim()
  if (mergedReverseMap[lower]) {
    variations.push(...mergedReverseMap[lower])
  }
  
  // Also check normalized version
  if (mergedReverseMap[normalized]) {
    variations.push(...mergedReverseMap[normalized])
  }
  
  return Array.from(new Set(variations)) // Remove duplicates
}

// Shared function to load school stats using the same logic as the schools page
interface SchoolStatsData {
  school: string
  nhsca_champions: number
  nchsaa_champions: number
  nhsca_placers: number
  nchsaa_placers: number
}

async function loadSchoolStatsFromDatabase(adminClient: any): Promise<Map<string, SchoolStatsData>> {
  // Fetch NHSCA data (placement 1-8) - same as schools page
  const { data: nhscaData, error: nhscaError } = await adminClient
    .from("wrestling_nhsca_results")
    .select("high_school, placement")
    .not("high_school", "is", null)
    .neq("high_school", "")
    .gte("placement", 1)
    .lte("placement", 8)
    .order("high_school")
    .limit(10000)

  if (nhscaError) throw nhscaError

  // Fetch NCHSAA data (place 1-8) using pagination - same as schools page
  let allNchsaaData: any[] = []
  let offset = 0
  const batchSize = 1000
  let hasMore = true

  while (hasMore) {
    const { data: batch, error: batchError } = await adminClient
      .from("wrestling_nchsaa_results")
      .select("school, place")
      .not("school", "is", null)
      .neq("school", "")
      .gte("place", 1)
      .lte("place", 8)
      .order("school")
      .range(offset, offset + batchSize - 1)

    if (batchError) throw batchError

    if (batch && batch.length > 0) {
      allNchsaaData = [...allNchsaaData, ...batch]
      offset += batchSize
      hasMore = batch.length === batchSize
    } else {
      hasMore = false
    }
  }

  // Group by school (normalized to lowercase) - same as schools page
  const schoolStatsMap = new Map<string, SchoolStatsData>()

  if (nhscaData && Array.isArray(nhscaData)) {
    nhscaData.forEach((result) => {
      if (!result?.high_school) return

      const schoolName = result.high_school.trim()
      const normalizedName = schoolName.toLowerCase()

      if (!schoolStatsMap.has(normalizedName)) {
        schoolStatsMap.set(normalizedName, {
          school: schoolName,
          nhsca_champions: 0,
          nchsaa_champions: 0,
          nhsca_placers: 0,
          nchsaa_placers: 0,
        })
      }

      const stats = schoolStatsMap.get(normalizedName)!
      stats.nhsca_placers++
      if (result.placement === 1) {
        stats.nhsca_champions++
      }
    })
  }

  if (allNchsaaData && Array.isArray(allNchsaaData)) {
    allNchsaaData.forEach((result) => {
      if (!result?.school) return

      const schoolName = result.school.trim()
      const normalizedName = schoolName.toLowerCase()

      if (!schoolStatsMap.has(normalizedName)) {
        schoolStatsMap.set(normalizedName, {
          school: schoolName,
          nhsca_champions: 0,
          nchsaa_champions: 0,
          nhsca_placers: 0,
          nchsaa_placers: 0,
        })
      }

      const stats = schoolStatsMap.get(normalizedName)!
      stats.nchsaa_placers++
      if (result.place === 1) {
        stats.nchsaa_champions++
      }
    })
  }

  return schoolStatsMap
}

