// Helper function to calculate Levenshtein distance for fuzzy matching
function levenshteinDistance(str1: string, str2: string): number {
  const matrix: number[][] = []
  const len1 = str1.length
  const len2 = str2.length

  for (let i = 0; i <= len1; i++) {
    matrix[i] = [i]
  }

  for (let j = 0; j <= len2; j++) {
    matrix[0][j] = j
  }

  for (let i = 1; i <= len1; i++) {
    for (let j = 1; j <= len2; j++) {
      if (str1[i - 1] === str2[j - 1]) {
        matrix[i][j] = matrix[i - 1][j - 1]
      } else {
        matrix[i][j] = Math.min(
          matrix[i - 1][j] + 1,
          matrix[i][j - 1] + 1,
          matrix[i - 1][j - 1] + 1
        )
      }
    }
  }

  return matrix[len1][len2]
}

// Helper function to find similar names when no exact match is found
async function findSimilarNames(
  searchTerm: string,
  adminClient: any,
  limit: number = 10
): Promise<string[]> {
  // First normalize common misspellings, then normalize to lowercase
  const misspellingNormalized = normalizeCommonMisspellings(searchTerm)
  const normalized = misspellingNormalized.toLowerCase().trim()
  const parts = normalized.split(/\s+/)
  
  // If it's just a last name, search for all people with that last name
  if (parts.length === 1) {
    const { data: lastNames } = await adminClient
      .from("athletes")
      .select("name")
      .ilike("name", `%${parts[0]}%`)
      .limit(limit)
    
    if (lastNames && lastNames.length > 0) {
      return Array.from(new Set(lastNames.map((a: any) => a.name).slice(0, limit)))
    }
    
    // Also check NCHSAA and NHSCA results
    const [nchsaaData, nhscaData] = await Promise.all([
      adminClient.from("wrestling_nchsaa_results").select("wrestler_name").ilike("wrestler_name", `%${parts[0]}%`).limit(limit),
      adminClient.from("wrestling_nhsca_results").select("athlete_name").ilike("athlete_name", `%${parts[0]}%`).limit(limit)
    ])
    
    const allNames = new Set<string>()
    if (nchsaaData.data) nchsaaData.data.forEach((r: any) => allNames.add(r.wrestler_name))
    if (nhscaData.data) nhscaData.data.forEach((r: any) => allNames.add(r.athlete_name))
    
    return Array.from(allNames).slice(0, limit)
  }
  
  // For full names, try fuzzy matching with improved scoring
  const searchFirst = parts[0] || ""
  const searchLast = parts[parts.length - 1] || ""
  // Include NCHSAA/NHSCA names so we get "Hickey, Gavin" when user types "Gavin Hickey"
  const [athletesRes, nchsaaRes, nhscaRes] = await Promise.all([
    adminClient.from("athletes").select("name").limit(1000),
    searchLast ? adminClient.from("wrestling_nchsaa_results").select("wrestler_name").or(`wrestler_name.ilike.%${searchLast}%,wrestler_name.ilike.%${searchLast},%`).limit(200) : { data: [] },
    searchLast ? adminClient.from("nhsca_placements").select("athlete_name").ilike("athlete_name", `%${searchLast}%`).limit(200) : { data: [] }
  ])
  const allAthletes = athletesRes?.data || []
  const nchsaaNames = (nchsaaRes?.data || []).map((r: any) => r.wrestler_name)
  const nhscaNames = (nhscaRes?.data || []).map((r: any) => r.athlete_name)
  const allNamesForScoring = Array.from(new Set([...allAthletes.map((a: any) => a.name), ...nchsaaNames, ...nhscaNames]))
  
  if (allNamesForScoring.length === 0) return []
  
  // Calculate similarity scores with emphasis on last name matching
  const scored = allNamesForScoring.map((rawName: string) => {
    const name = rawName.toLowerCase()
    const nameParts = name.split(/\s+/)
    const nameFirst = nameParts[0] || ""
    const nameLast = nameParts[nameParts.length - 1] || ""
    
    // Overall name similarity
    const fullDistance = levenshteinDistance(normalized, name)
    const maxLen = Math.max(normalized.length, name.length)
    const fullSimilarity = 1 - (fullDistance / maxLen)
    
    // Last name similarity (weighted more heavily)
    let lastSimilarity = 0
    if (searchLast && nameLast) {
      const lastDistance = levenshteinDistance(searchLast, nameLast)
      const maxLastLen = Math.max(searchLast.length, nameLast.length)
      lastSimilarity = 1 - (lastDistance / maxLastLen)
    }
    
    // First name similarity
    let firstSimilarity = 0
    if (searchFirst && nameFirst) {
      const firstDistance = levenshteinDistance(searchFirst, nameFirst)
      const maxFirstLen = Math.max(searchFirst.length, nameFirst.length)
      firstSimilarity = 1 - (firstDistance / maxFirstLen)
    }
    
    // Combined score: 50% last name, 30% first name, 20% full name
    // This ensures "Johathan Millner" matches "Jonathan Millner" better than "Jordan Miller"
    const combinedSimilarity = (lastSimilarity * 0.5) + (firstSimilarity * 0.3) + (fullSimilarity * 0.2)
    
    return { name: rawName, similarity: combinedSimilarity, lastSimilarity, firstSimilarity }
  })
  
  // Filter by similarity threshold (0.5 = 50% similar) and sort
  // Lower threshold because we're combining multiple factors
  const names = scored
    .filter((s: any) => s.similarity >= 0.5 || s.lastSimilarity >= 0.7) // High last name match is important
    .sort((a: any, b: any) => {
      // Prioritize last name matches, then overall similarity
      if (Math.abs(a.lastSimilarity - b.lastSimilarity) > 0.1) {
        return b.lastSimilarity - a.lastSimilarity
      }
      return b.similarity - a.similarity
    })
    .slice(0, limit)
    .map((s: any) => s.name)
  // Dedupe so we don't show "Luke Richards" twice when DB has duplicate rows
  return Array.from(new Set(names))
}

// Helper function to deduplicate school names that are variations of the same school
// e.g., "Uwharrie Charter", "Uwharrie Charter Academy", "Uwharries Charter" -> "Uwharrie Charter"
function deduplicateSchoolNames(schools: Set<string>): string[] {
  if (schools.size <= 1) return Array.from(schools)
  
  const schoolArray = Array.from(schools)
  const normalizedGroups = new Map<string, string[]>()
  
  // Normalize school name for comparison
  const normalize = (name: string): string => {
    return name
      .toLowerCase()
      .replace(/\s+(high\s+school|highschool|hs|academy|school)$/i, "")
      .replace(/s$/, "") // Remove trailing 's' (e.g., "Uwharries" -> "Uwharrie")
      .replace(/['']/g, "") // Remove apostrophes
      .trim()
  }
  
  // Group schools by their normalized form
  for (const school of schoolArray) {
    const normalized = normalize(school)
    if (!normalizedGroups.has(normalized)) {
      normalizedGroups.set(normalized, [])
    }
    normalizedGroups.get(normalized)!.push(school)
  }
  
  // For each group, pick the shortest name (usually the canonical form)
  const deduplicated: string[] = []
  for (const [_, variations] of normalizedGroups) {
    // Sort by length (shortest first), then alphabetically
    variations.sort((a, b) => a.length - b.length || a.localeCompare(b))
    deduplicated.push(variations[0])
  }
  
  return deduplicated
}

