          return NextResponse.json({
            answer: `I couldn't find any ${countText}NHSCA All-Americans in the database.${targetCount ? ` There may not be any wrestlers who have earned All-American status exactly ${targetCount} times.` : ""}`,
            messageId: messageId || `msg-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
            queryType: "multiple_time_nhsca_all_americans"
          })
