      console.log(`[AI]   - Raw NCHSAA: ${nchsaaResults?.data?.length || 0}, Filtered: ${filteredNchsaa.length}`)
      console.log(`[AI]   - Raw NHSCA: ${nhscaResults?.data?.length || 0}, Filtered: ${filteredNhsca.length}`)
