        // Capitalize first letter of each word for database queries
        // But preserve abbreviations (2 characters or less, all uppercase) like "AL", "A.L."
        let schoolName = schoolNameRaw.split(/\s+/).map(word => {
        // If word is 2 characters or less and all uppercase, preserve it (likely an abbreviation like "AL")
        if (word.length <= 2 && word === word.toUpperCase() && /^[A-Z]+$/.test(word)) {
          return word // Preserve "AL" as "AL"
        }
        // If word has periods and is short, might be abbreviation like "A.L." - preserve structure
        if (word.match(/^[A-Z]\.([A-Z]\.)?$/i)) {
          return word.toUpperCase() // "a.l." -> "A.L."
        }
        // Otherwise, capitalize normally
        return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase()
        }).join(" ")
