          const totalMOWWinners = mowWinners?.length || 0
          const totalDualTeamChamps = dualTeamChamps?.filter((c: any) => !c.is_vacated).length || 0
          const totalDaveSchultzWinners = daveSchultzWinners?.length || 0
          
