              // Normalize weight field - remove "lbs" suffixes to prevent "lbslbs"
              const weight = ((aa.weight || aa.weight_class || "").toString().replace(/lbs?$/i, "").trim())
              const divisionText = aa.division && aa.division.trim() ? `${aa.division}, ` : ""
              summaryLines.push(`- ${aa.year}: ${aa.athlete_name || aa.name} - ${placementText} (${divisionText}${weight}lbs)`)
