            const totalStatePlacers = (statePlacers && statePlacers.length > 0) ? statePlacers.length : 0
          // Count all All-American achievements (each achievement in the map = 1)
          const totalNhscaAAs = allNhscaAAs.size
            const totalDualTeamChamps = (dualTeamChamps && dualTeamChamps.length > 0) ? dualTeamChamps.filter((c: any) => !c.is_vacated).length : 0
            const totalDaveSchultzWinners = (daveSchultzWinners && daveSchultzWinners.length > 0) ? daveSchultzWinners.length : 0
          
