    // If it's a state tournament schedule query, skip calendar handler - let schedule handler process it
    const shouldSkipCalendarForSchedule = isStateTournamentScheduleQueryPreCheck
    
    // CRITICAL PRE-FILTER: Catch ALL calendar queries FIRST - route to calendar handler
    // This catches "when is/are" questions about events that should be in the calendar
