        console.log("[AI] Handler triggered: isWhoWonStateChampionQuestion")
        
        // Extract classification
        const classificationMatch = lowerQuestion.match(/\b([1-8]a)\b/i)
        const classification = classificationMatch ? classificationMatch[1].toUpperCase() : null

        // Extract weight class - handle variations like "132lbs", "132 lbs", "132"
        const weightMatch = lowerQuestion.match(/\b(106|113|120|126|132|138|144|150|157|165|175|190|215|285)\s*(?:lbs|pounds)?\b/i)
        const weight = weightMatch ? weightMatch[1] : null

        // Extract year - handle "last year" as 2024
        let year: number | null = null
