    const whoAreAllAmericansPattern = /(?:who are|who were|list|show all|show).*?(?:the\s+)?(?:all\s+americans?|all-americans?|allamericans?).*?(?:from|at)\s+([a-zA-Z]+(?:\s+[a-zA-Z]+)+(?:\s+(?:High School|HS|School))?)/i
    const whoAreAllAmericansMatch = message.match(whoAreAllAmericansPattern) // Use original message to preserve case
    
